package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import android.media.*;import android.media.session.*;import java.util.concurrent.atomic.*;
public class LockScreenControlsTest extends Instrumentation {
    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    void ui(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{task.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier predicate,String message)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){AtomicBoolean done=new AtomicBoolean();ui(()->done.set(predicate.getAsBoolean()));if(done.get())return;Thread.sleep(40);}throw new AssertionError(message);}
    void shell(String command)throws Exception{try(java.io.InputStream output=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command))){byte[] bytes=new byte[256];while(output.read(bytes)!=-1){}}Thread.sleep(300);}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();MainActivity activity=null;boolean passed=false;try{
        activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","lock_controls_qa").putExtra("book_name","我爱听书 · 锁屏控制").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.system.initialized&&a.offlineReady,"voices not ready");ui(()->{StringBuilder text=new StringBuilder();for(int chapter=1;chapter<=3;chapter++){text.append("第").append(chapter).append("章 山间的风\n");for(int i=0;i<25;i++)text.append("风吹过山间，书页轻轻翻动。戴上耳机，让每一段文字都有声音。\n");}a.text=text.toString();a.chapters=MainActivity.parse(a.text);a.chapter=1;a.position=a.chapters.get(1).start;a.readingLanguage="";a.loopPlayback=false;a.rate=1.8f;SystemSpeaker.Option voice=a.system.offlineVoice("zh","");check(voice!=null,"system voice missing");a.systemVoiceKey=voice.key;a.showPosition(true);a.startReading();});await(()->PlaybackService.active!=null&&PlaybackService.active.session.getController().getMetadata()!=null,"media metadata missing");final MediaController controller=PlaybackService.active.session.getController();long actions=controller.getPlaybackState().getActions();check((actions&PlaybackState.ACTION_SKIP_TO_PREVIOUS)!=0&&(actions&PlaybackState.ACTION_SKIP_TO_NEXT)!=0&&(actions&PlaybackState.ACTION_SEEK_TO)!=0,"missing lock screen actions");check(controller.getMetadata().getLong(MediaMetadata.METADATA_KEY_DURATION)>0,"missing scrubber duration");check(controller.getMetadata().getString(MediaMetadata.METADATA_KEY_ARTIST).contains("时长估算"),"estimated timeline not labeled");
        shell("input keyevent 3");shell("input keyevent 223");check(!getTargetContext().getSystemService(PowerManager.class).isInteractive(),"screen not off");await(()->!a.readerVisible,"reader not in background");Thread.sleep(2500);ui(()->check(PlaybackService.active.state.fraction>0,"reading progress not published while locked"));controller.getTransportControls().skipToNext();await(()->a.chapter==2&&a.playing,"lock next failed");controller.getTransportControls().skipToPrevious();await(()->a.chapter==1&&a.playing,"lock previous failed");controller.getTransportControls().pause();await(()->!a.playing&&PlaybackService.active!=null&&!PlaybackService.active.foreground&&!PlaybackService.active.wake.isHeld(),"lock pause retained foreground/wake or removed controls");await(()->controller.getPlaybackState().getState()==PlaybackState.STATE_PAUSED,"paused state not published");long duration=controller.getMetadata().getLong(MediaMetadata.METADATA_KEY_DURATION);controller.getTransportControls().seekTo(duration/2);await(()->a.mediaState().fraction>.35f&&a.mediaState().fraction<.6f&&!a.playing,"paused seek did not map to source paragraph");controller.getTransportControls().play();await(()->a.playing&&PlaybackService.active!=null&&PlaybackService.active.foreground,"lock resume failed");result.putBoolean("previousNextWhileLocked",true);result.putBoolean("pauseSeekResumeWhileLocked",true);
        shell("input keyevent 224");Thread.sleep(1000);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),"lock-controls-qa.png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}controller.getTransportControls().stop();await(()->!a.playing&&PlaybackService.active==null&&CpuWork.active.get()==0,"media stop leaked resources");result.putString("result","PASS: source-derived estimated chapter timeline; chapter progress while locked; previous/next callbacks; pause keeps media controls with no foreground/wake; source-aligned seek; resume; stop cleanup");passed=true;
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{try{shell("input keyevent 224");}catch(Exception ignored){}if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}getTargetContext().getSharedPreferences("reader_lock_controls_qa",0).edit().clear().commit();}finish(passed?-1:0,result);}
}
